# Deadly Plot (FDN) -- Choose one --
#  * Destroy target creature or planeswalker.  (M21 Finishing Blow's B5a-destroy-cw-pw atom)
#  * Return target Zombie creature card from your graveyard to the battlefield tapped.
#      M21 Rise Again's B5b-return-creatures-battlefield move, the filter a Zombie creature card
#      (SUBTYPE_EQ Zombie + TYPE_EQ Creature), entering tapped (`tapped_on_enter`).
abilities = [
    SpellAbility(
        kind=SpellKind.INSTANT,
        effect=Choose(
            count=QConst(value=1),
            options=(
                A(Verb.DESTROY, {
                    'target': Selector(
                        count=QConst(value=1),
                        mode=SelectorMode.TARGET,
                        filter=FOr(
                            children=(
                                FAtom(pred=FAtomPred.TYPE_EQ, string_value='Creature'),
                                FAtom(pred=FAtomPred.TYPE_EQ, string_value='Planeswalker'),
                            ),
                        ),
                        zones=(Zone(kind=ZoneKind.BATTLEFIELD, controller=ControllerRef.ANY),),
                    ),
                }),
                A(Verb.MOVE_ZONE, {
                    'cards': Selector(
                        count=QConst(value=1),
                        mode=SelectorMode.TARGET,
                        filter=FAnd(
                            children=(
                                FAtom(pred=FAtomPred.SUBTYPE_EQ, string_value='Zombie'),
                                FAtom(pred=FAtomPred.TYPE_EQ, string_value='Creature'),
                            ),
                        ),
                        zones=(Zone(kind=ZoneKind.GRAVEYARD, controller=ControllerRef.YOU),),
                    ),
                    'destination': Zone(kind=ZoneKind.BATTLEFIELD, controller=ControllerRef.ANY),
                    'tapped_on_enter': True,
                }),
            ),
        ),
    ),
]
